{"checks":[
  {
    "scenario":"REQ-2.5.1#1",
    "requirement":"REQ-2.5.1",
    "title":"Archive",
    "category":"state-toggle",
    "rationale":"The note 'Travel plans 2.5.1' is seeded as active. Archive it from its note card, then confirm it is removed from the home list, the Undo notification appears, and it is visible in the Archived view when the sidebar link is used.",
    "given":[
      {"op":"open"},
      {"op":"expectText","target":{"name":["Travel plans 2.5.1"],"via":"text"}},
      {"op":"hover","target":{"name":["Travel plans 2.5.1"],"via":"text"}}
    ],
    "when":[
      {"op":"click","target":{"name":["Archive"],"via":"ladder","within":{"name":["Travel plans 2.5.1"],"via":"text"}}}
    ],
    "then":[
      {"op":"expectText","target":{"name":["Undo"],"via":"ladder"}},
      {"op":"expectAbsent","target":{"name":["Travel plans 2.5.1"],"via":"text"}},
      {"op":"click","target":{"name":["Archived"],"via":"role","role":"link"}},
      {"op":"expectText","target":{"name":["Travel plans 2.5.1"],"via":"text"}}
    ]
  },
  {
    "scenario":"REQ-2.5.2#1",
    "requirement":"REQ-2.5.2",
    "title":"Archive Undo",
    "category":"state-toggle",
    "rationale":"The scenario begins with the archive notification visible, so the active seed note 'Travel plans 2.5.2' is archived first. Clicking Undo should restore it to the home notes list, which is verified by its presence on the home page.",
    "given":[
      {"op":"open"},
      {"op":"expectText","target":{"name":["Travel plans 2.5.2"],"via":"text"}},
      {"op":"hover","target":{"name":["Travel plans 2.5.2"],"via":"text"}},
      {"op":"click","target":{"name":["Archive"],"via":"ladder","within":{"name":["Travel plans 2.5.2"],"via":"text"}}},
      {"op":"expectText","target":{"name":["Undo"],"via":"ladder"}}
    ],
    "when":[
      {"op":"click","target":{"name":["Undo"],"via":"ladder"}}
    ],
    "then":[
      {"op":"expectText","target":{"name":["Travel plans 2.5.2"],"via":"text"}}
    ]
  },
  {
    "scenario":"REQ-2.5.3#1",
    "requirement":"REQ-2.5.3",
    "title":"Show archived notes",
    "category":"read-list",
    "rationale":"The seed note 'Travel plans 2.5.3' is active. It must be archived first to create archived content, then the Archived sidebar item opens the archived list where the note should be visible.",
    "given":[
      {"op":"open"},
      {"op":"expectText","target":{"name":["Travel plans 2.5.3"],"via":"text"}},
      {"op":"hover","target":{"name":["Travel plans 2.5.3"],"via":"text"}},
      {"op":"click","target":{"name":["Archive"],"via":"ladder","within":{"name":["Travel plans 2.5.3"],"via":"text"}}}
    ],
    "when":[
      {"op":"click","target":{"name":["Archived"],"via":"role","role":"link"}}
    ],
    "then":[
      {"op":"expectText","target":{"name":["Travel plans 2.5.3"],"via":"text"}}
    ]
  },
  {
    "scenario":"REQ-2.5.4#1",
    "requirement":"REQ-2.5.4",
    "title":"Unarchive",
    "category":"state-toggle",
    "rationale":"The seed note 'Travel plans 2.5.4' is active. After archiving it and opening the Archived list, the Unarchive action should move it out of the archived list and back to the main Notes list, verified by its absence in Archived and presence after clicking Notes.",
    "given":[
      {"op":"open"},
      {"op":"expectText","target":{"name":["Travel plans 2.5.4"],"via":"text"}},
      {"op":"hover","target":{"name":["Travel plans 2.5.4"],"via":"text"}},
      {"op":"click","target":{"name":["Archive"],"via":"ladder","within":{"name":["Travel plans 2.5.4"],"via":"text"}}},
      {"op":"click","target":{"name":["Archived"],"via":"role","role":"link"}},
      {"op":"expectText","target":{"name":["Travel plans 2.5.4"],"via":"text"}}
    ],
    "when":[
      {"op":"hover","target":{"name":["Travel plans 2.5.4"],"via":"text"}},
      {"op":"click","target":{"name":["Unarchive"],"via":"ladder","within":{"name":["Travel plans 2.5.4"],"via":"text"}}}
    ],
    "then":[
      {"op":"expectAbsent","target":{"name":["Travel plans 2.5.4"],"via":"text"}},
      {"op":"click","target":{"name":["Notes"],"via":"role","role":"link"}},
      {"op":"expectText","target":{"name":["Travel plans 2.5.4"],"via":"text"}}
    ]
  }
]}
